using MediatR; using OrderingService.Application.Abstractions; using OrderingService.Application.IntegrationEvents; using OrderingService.Application.Outbox; using OrderingService.Domain.Fulfillment; using OrderingService.Domain.Orders;
namespace OrderingService.Application.Fulfillment;
public sealed class DeliverShipmentHandler(IOrderingUnitOfWork unitOfWork,IOrderRepository orders,IShipmentRepository shipments,IOutboxRepository outbox):IRequestHandler<DeliverShipmentCommand,ShipmentDto?>
{ public Task<ShipmentDto?> Handle(DeliverShipmentCommand r,CancellationToken ct)=>unitOfWork.ExecuteAsync(async tx=>{var shipment=await shipments.GetByOrderIdAsync(r.OrderId,tx,ct);if(shipment is null)return null;if(shipment.Status==ShipmentStatus.Delivered)return ShipmentMapper.ToDto(shipment);var order=await orders.GetByIdAsync(r.OrderId,tx,ct)??throw new InvalidOperationException("Shipment order is missing.");var prior=shipment.Status;shipment.Deliver(DateTime.UtcNow);if(!order.MoveToFulfillmentStatus(OrderStatus.Delivered))throw new InvalidOperationException("Order could not be marked delivered.");if(!await shipments.UpdateAsync(shipment,prior,tx,ct)||!await orders.TryUpdateStatusAsync(order.Id,order.Status,[OrderStatus.Shipped],tx,ct))throw new InvalidOperationException("Shipment changed before delivery.");await outbox.AddAsync(OutboxMessageFactory.Create(OrderIntegrationEventFactory.CreateOrderStatusChanged(order,OrderStatus.Shipped)),tx,ct);await outbox.AddAsync(OutboxMessageFactory.CreateKafka(OrderIntegrationEventFactory.CreateOrderProjectionStatusChanged(order,OrderStatus.Shipped)),tx,ct);await shipments.AddHistoryAsync(ShipmentStatusHistory.Create(shipment.Id,prior,shipment.Status,r.ActorId,"Shipment delivered.",DateTime.UtcNow),tx,ct);return ShipmentMapper.ToDto(shipment);},ct); }